export const getCreateGigUrl = () => {
  return `/api/v1/gigs`;
};

/**
 * Только customer. Автор определяется из сессии; создаётся open. startsAt > время сервера, endsAt > startsAt.
 * @summary Опубликовать подработку
 */
export const createGig = async (
  createGigRequest: CreateGigRequest,
  options?: Parameters<typeof http>[1],
): Promise<Gig> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return http<Gig>(getCreateGigUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(createGigRequest),
  });
};

